def _check_braces(self, format):
    '''Validate that braces are properly matched in the format string.'''
    # Track brace depth, ignoring escaped braces {{ and }}
    depth = 0
    i = 0
    while i < len(format):
        if i + 1 < len(format) and format[i:i+2] == '{{':
            i += 2
            continue
        elif i + 1 < len(format) and format[i:i+2] == '}}':
            i += 2
            continue
        elif format[i] == '{':
            depth += 1
        elif format[i] == '}':
            depth -= 1
            if depth < 0:
                raise ValueError("single '}' encountered in format string")
        i += 1
    if depth != 0:
        raise ValueError("single '{' encountered in format string, unmatched")

